namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, societies, and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. He previously worked at Google Research before joining academia.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases. Covers SQL, normalization, transaction processing, and query optimization.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez brings industry experience from Oracle and Microsoft to her teaching. Her research focuses on distributed database systems.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, Code = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible. He has authored two bestselling textbooks.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research spans abstract algebra and its applications in data science. She brings cutting-edge research into the classroom.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a former NASA researcher who brings real-world physics applications into the classroom. His demonstrations are legendary among students.", IsFeatured = true, DepartmentName = "Physics" },
            new() { Id = 7, DepartmentId = 3, Code = "PHYS 220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel's research in quantum electrodynamics informs her teaching of classical electromagnetism. She holds multiple patents in photonics.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 8, DepartmentId = 4, Code = "ENG 110", Title = "College Writing", Description = "Develop critical thinking and writing skills through essay composition, peer review, and revision strategies.", Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", InstructorName = "Prof. David Hart", InstructorBio = "Prof. Hart is a published novelist and essayist. He believes in the power of clear writing to transform thinking.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 9, DepartmentId = 4, Code = "ENG 225", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and culture.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Lisa Monroe", InstructorBio = "Dr. Monroe specializes in 20th-century American fiction. Her recent book on Toni Morrison received critical acclaim.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 10, DepartmentId = 5, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of human civilizations from ancient Mesopotamia through the late medieval period, covering political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed is an archaeologist-turned-historian whose fieldwork in the Middle East enriches his lectures with firsthand discoveries.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 11, DepartmentId = 5, Code = "HIST 240", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Examines nationalism, industrialization, world wars, and European integration.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois brings a Franco-American perspective to European history. She has held visiting positions at the Sorbonne and Oxford.", IsFeatured = false, DepartmentName = "History" }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

