@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request below. You will receive a confirmation from the registrar's office.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Request submitted!</strong> Your enrollment request has been received. The registrar's office will process it within 2–3 business days.
    </div>
    <a href="courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <form method="post" class="col-md-8">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" required />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code &mdash; @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public UniversityCourseCatalog.Models.EnrollmentRequest? Model { get; set; }
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> courses = new();
    private bool submitted;
    private string? errorMessage;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();
        Model ??= new() { CourseId = CourseId ?? 0 };
    }

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.StudentName is not null && Model.CourseId > 0)
        {
            // Form was posted
            if (string.IsNullOrWhiteSpace(Model.StudentName) || string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId == 0)
            {
                errorMessage = "Please fill in all fields.";
            }
            else if (CatalogService.SubmitEnrollmentRequest(Model))
            {
                submitted = true;
            }
            else
            {
                errorMessage = "Unable to process your request. Please verify the selected course.";
            }
        }
    }
}

